window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9a26f47137a0dfa3"]={"versions": [{"id": "FIG-9a26f47137a0dfa3", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing-Diagramm zur Darstellung des ereignisgesteuerten Übertragungsmodus (Transmission Mode DIRECT / N-Times) im AUTOSAR Communication Module (COM). Das Diagramm veranschaulicht das zeitliche Zusammenspiel zwischen Sendeanforderungen durch Signal-Aktualisierungen (v = x) und den resultierenden Sende- bzw. Wiederholungsvorgängen auf I-PDU-Ebene unter Einhaltung von Mindestabständen (Minimum Delay Timer / MDT).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zeitachse (t)</strong>: Horizontale Hauptachse mit Unterbrechungen zur Trennung einzelner Teilszenarien.\n</li><li><strong>Sendeaufruf-Ereignis (Blitzsymbol)</strong>: Signalisiert die Aktualisierung eines Signals bzw. einer Signal-Gruppe mit Sendeauslösung (v = x).\n</li><li><strong>Übertragungsimpulse (grüne vertikale Pfeile nach unten)</strong>: Tatsächlich durchgeführte I-PDU-Sendeaufrufe an die unterlagerte Schicht (PDU Router).\n</li><li><strong>Unterdrückte / verschobene Übertragungen (blau gestrichelte Pfeile)</strong>: Geplante Sende- oder Wiederholungsereignisse, die infolge einer erneuten Aktualisierung oder MDT-Überlappung neu getaktet werden.\n</li><li><strong>$t_{r,\\min}$</strong>: Mindestsendeabstand (Minimum Delay Time, MDT / Transmission Deadline / Repetition Period).\n</li><li><strong>t_d</strong>: Konfigurierter zeitlicher Abstand zwischen den n Wiederholungen (n = 3).\n</li><li><strong>dt</strong>: Zeitdifferenz bzw. Versatz zwischen aufeinanderfolgenden Ereignissen / Triggern.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm zeigt drei aufeinanderfolgende Szenarien für n = 3:</p>\n<ol class=\"fig-list\"><li><strong>Regulärer Burst (n = 3)</strong>: Ein Sendeereignis triggert nach einer minimalen Verzögerungszeit $t_{r,\\min}$ die erste I-PDU-Aussendung, gefolgt von zwei weiteren Wiederholungen im festen Zeitabstand t_d.\n</li><li><strong>Re-Triggerung außerhalb des Mindestabstands</strong>: Nach dem ersten Sendeaufruf erfolgt während der Wiederholungsphase eine erneute Signalaktualisierung. Da der Abstand zur vorherigen Übertragung größer als $t_{r,\\min}$ ist, wird der Wiederholungszyklus (n = 3) ab dem neuen Trigger-Zeitpunkt unmittelbar neu gestartet; die noch ausstehende Wiederholung der vorherigen Folge wird überschrieben/abgebrochen.\n</li><li><strong>Re-Triggerung innerhalb des Mindestabstands ($dt &lt; t_{r,\\min}$)</strong>: Trifft eine neue Signalaktualisierung kurz nach einer Übertragung ein, erzwingt $t_{r,\\min}$ das Verstreichen des Mindestabstands, bevor der neue n-fache Sendezyklus mit dem ersten Impuls beginnen kann. Die nachfolgenden Aussendungen erfolgen wieder im äquidistanten Abstand t_d.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm konkretisiert die normativen Anforderungen des AUTOSAR COM bezüglich der I-PDU-Sendearten (<code>DIRECT</code> / <code>N-Times</code> mit <code>ComTxModeNumberOfRepetitions = 2</code>, d. h. 1 Erstsendung + 2 Wiederholungen = 3 Aussendungen):</p>\n<ul class=\"fig-list\"><li>Jede Aktualisierung eines Signals, das für die Übertragung konfiguriert ist, initiiert eine Folge von n Übertragungen im Abstand von <code>ComTxModeRepetitionPeriod</code> (t_d).\n</li><li>Trifft ein neuer Übertragungswunsch ein, während eine Übertragungsfolge noch aktiv ist, startet die Sequenz von n Übertragungen neu.\n</li><li>Das Versenden jeder I-PDU unterliegt zwingend der Begrenzung durch den Minimum Delay Timer (<code>ComMinimumDelayTime</code> / $t_{r,\\min}$); vor Ablauf dieses Timers darf keine I-PDU an den PDU Router übergeben werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-2a23c963d61f7807", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing-Diagramm zur Darstellung des ereignisgesteuerten Übertragungsmodus (Transmission Mode DIRECT / N-Times) im AUTOSAR Communication Module (COM). Das Diagramm veranschaulicht das zeitliche Zusammenspiel zwischen Sendeanforderungen durch Signal-Aktualisierungen (v = x) und den resultierenden Sende- bzw. Wiederholungsvorgängen auf I-PDU-Ebene unter Einhaltung von Mindestabständen (Minimum Delay Timer / MDT).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zeitachse (t)</strong>: Horizontale Hauptachse mit Abschnittsunterbrechungen.\n</li><li><strong>Sendeaufruf-Ereignis (rotes Dreiecksymbol / Trichter)</strong>: Repräsentiert die Aktualisierung eines Signals bzw. die Sendeauslösung (v = x).\n</li><li><strong>Übertragungsimpulse (grüne vertikale Pfeile nach unten)</strong>: Tatsächlich ausgeführte Aussendungen der I-PDU an die untere Schicht.\n</li><li><strong>Re-getaktete / verworfene Übertragungszeitpunkte (blaue Pfeile / gestrichelte Linien)</strong>: Ursprünglich geplante Sendezeitpunkte, die durch eine zwischenzeitliche Re-Triggerung modifiziert werden.\n</li><li><strong>t_r</strong>: Mindestsendeabstand (Minimum Delay Time, MDT), markiert durch geschwungene Klammern unterhalb der Ereignislinien.\n</li><li><strong>t_d</strong>: Konfigurierter Wiederholungsabstand (<code>ComTxModeRepetitionPeriod</code>) zwischen den Übertragungen der Serie (n = 3).\n</li><li><strong>d</strong>: Zeitdifferenz bzw. zeitlicher Versatz zwischen aufeinanderfolgenden Ereignissen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm zeigt drei aufeinanderfolgende Szenarien für n = 3:</p>\n<ol class=\"fig-list\"><li><strong>Regulärer Burst (n = 3)</strong>: Ein Sendeereignis triggert nach einer minimalen Verzögerungszeit $t_{r,\\min}$ die erste I-PDU-Aussendung, gefolgt von zwei weiteren Wiederholungen im festen Zeitabstand t_d.\n</li><li><strong>Re-Triggerung außerhalb des Mindestabstands</strong>: Nach dem ersten Sendeaufruf erfolgt während der Wiederholungsphase eine erneute Signalaktualisierung. Da der Abstand zur vorherigen Übertragung größer als $t_{r,\\min}$ ist, wird der Wiederholungszyklus (n = 3) ab dem neuen Trigger-Zeitpunkt unmittelbar neu gestartet; die noch ausstehende Wiederholung der vorherigen Folge wird überschrieben/abgebrochen.\n</li><li><strong>Re-Triggerung innerhalb des Mindestabstands ($dt &lt; t_{r,\\min}$)</strong>: Trifft eine neue Signalaktualisierung kurz nach einer Übertragung ein, erzwingt $t_{r,\\min}$ das Verstreichen des Mindestabstands, bevor der neue n-fache Sendezyklus mit dem ersten Impuls beginnen kann. Die nachfolgenden Aussendungen erfolgen wieder im äquidistanten Abstand t_d.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm konkretisiert die normativen Anforderungen des AUTOSAR COM bezüglich der I-PDU-Sendearten (<code>DIRECT</code> / <code>N-Times</code> mit <code>ComTxModeNumberOfRepetitions = 2</code>, d. h. 1 Erstsendung + 2 Wiederholungen = 3 Aussendungen):</p>\n<ul class=\"fig-list\"><li>Jede Aktualisierung eines Signals, das für die Übertragung konfiguriert ist, initiiert eine Folge von n Übertragungen im Abstand von <code>ComTxModeRepetitionPeriod</code> (t_d).\n</li><li>Trifft ein neuer Übertragungswunsch ein, während eine Übertragungsfolge noch aktiv ist, startet die Sequenz von n Übertragungen neu.\n</li><li>Das Versenden jeder I-PDU unterliegt zwingend der Begrenzung durch den Minimum Delay Timer (<code>ComMinimumDelayTime</code> / $t_{r,\\min}$); vor Ablauf dieses Timers darf keine I-PDU an den PDU Router übergeben werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-9a26f47137a0dfa3", "to": "FIG-2a23c963d61f7807", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>Ereignissymbole für Sendeaufrufe</strong>: Die orangefarbenen Blitzsymbole oberhalb der Zeitachse wurden durch braun-rote Dreiecks-/Trichter-Symbole ersetzt.\n</li><li><strong>Klammer- und Maßhilfslinien</strong>: Zeitspannen $t_{r,\\min}$ bzw. t_r und dt bzw. d werden nicht mehr über einfache Pfeile zwischen Hilfslinien dargestellt, sondern über geschwungene Klammern unterhalb der jeweiligen Referenzlinien.\n</li><li><strong>Formelzeichen und Indizes</strong>: Der Mindestsendeabstand ist nun als t_r statt als $t_{r,\\min}$ beschriftet; das Differenzintervall ist als d statt als dt bezeichnet.\n</li><li><strong>Pfeilplatzierung für Wiederholungsabstand</strong>: Der blaue Pfeil für t_d liegt nun oberhalb der Zeitachse (als vertikaler Pfeil) bzw. ist direkt über der Zeitachse vermessen, anstatt unterhalb der Zeitachse gezeichnet zu sein.\n</li><li><strong>Allgemeines Rendering</strong>: Schriftarten, Linienstärken und Vektorstile wurden an das modernere AUTOSAR-Diagrammlayout angepasst.\n</li></ul>"}]};
